-- Campus Shopping / Mingde Chinese-English School
-- PostgreSQL 15+ | DESIGN DRAFT - NOT EXECUTED
-- Reconcile with application models and test on isolated DB before production.
BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS citext;
CREATE SCHEMA IF NOT EXISTS campus;
SET search_path=campus,public;
CREATE TABLE school_config(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_code text UNIQUE NOT NULL DEFAULT 'MINGDE',school_name text NOT NULL DEFAULT '明德中英文学校',timezone text NOT NULL DEFAULT 'Asia/Shanghai',config jsonb NOT NULL DEFAULT '{}');
CREATE TABLE grades(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text UNIQUE NOT NULL,sort_order int NOT NULL DEFAULT 0,active boolean NOT NULL DEFAULT true);
CREATE TABLE classes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),grade_id uuid REFERENCES grades(id),name text NOT NULL,school_year text,active boolean NOT NULL DEFAULT true,UNIQUE(grade_id,name,school_year));
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_no text UNIQUE,display_name text NOT NULL,email citext UNIQUE,phone text UNIQUE,password_hash text,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','locked','disabled','pending')),user_type text NOT NULL CHECK(user_type IN('student','parent','staff','merchant','admin')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE student_profiles(user_id uuid PRIMARY KEY REFERENCES users(id),student_no text UNIQUE NOT NULL,class_id uuid REFERENCES classes(id),guardian_user_id uuid REFERENCES users(id),enrollment_status text NOT NULL DEFAULT 'active');
CREATE TABLE roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text UNIQUE NOT NULL,name text NOT NULL);
CREATE TABLE permissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text UNIQUE NOT NULL,description text);
CREATE TABLE role_permissions(role_id uuid REFERENCES roles(id),permission_id uuid REFERENCES permissions(id),PRIMARY KEY(role_id,permission_id));
CREATE TABLE user_roles(user_id uuid REFERENCES users(id),role_id uuid REFERENCES roles(id),granted_by uuid REFERENCES users(id),granted_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,role_id));
CREATE TABLE founder_authorizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),principal_user_id uuid NOT NULL REFERENCES users(id),action_code text NOT NULL,granted_by uuid REFERENCES users(id),active boolean NOT NULL DEFAULT true,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE auth_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),refresh_token_hash text UNIQUE NOT NULL,device_fingerprint_hash text,ip inet,user_agent text,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE verification_codes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),subject text NOT NULL,purpose text NOT NULL,code_hash text NOT NULL,expires_at timestamptz NOT NULL,consumed_at timestamptz,attempts smallint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE login_events(id bigserial PRIMARY KEY,user_id uuid REFERENCES users(id),subject text,success boolean NOT NULL,reason_code text,ip inet,device_hash text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE merchants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_user_id uuid NOT NULL REFERENCES users(id),merchant_no text UNIQUE NOT NULL,name text NOT NULL,merchant_type text NOT NULL,risk_level text NOT NULL DEFAULT 'normal',status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','active','paused','exiting','closed')),contact_info jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE merchant_members(merchant_id uuid REFERENCES merchants(id),user_id uuid REFERENCES users(id),member_role text NOT NULL,active boolean NOT NULL DEFAULT true,PRIMARY KEY(merchant_id,user_id));
CREATE TABLE merchant_policies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),merchant_id uuid REFERENCES merchants(id),policy_type text NOT NULL,value jsonb NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz,approved_by uuid REFERENCES users(id),reason text NOT NULL);
CREATE TABLE categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),parent_id uuid REFERENCES categories(id),name text NOT NULL,sort_order int NOT NULL DEFAULT 0,active boolean NOT NULL DEFAULT true);
CREATE TABLE products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),merchant_id uuid NOT NULL REFERENCES merchants(id),category_id uuid REFERENCES categories(id),title text NOT NULL,description text,product_type text NOT NULL DEFAULT 'physical',status text NOT NULL DEFAULT 'draft',cover_url text,deleted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE product_media(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES products(id),media_type text NOT NULL CHECK(media_type IN('image','video')),object_key text NOT NULL,sort_order int NOT NULL DEFAULT 0);
CREATE TABLE product_options(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES products(id),option_name text NOT NULL,sort_order int NOT NULL DEFAULT 0);
CREATE TABLE product_option_values(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),option_id uuid NOT NULL REFERENCES product_options(id),value text NOT NULL,sort_order int NOT NULL DEFAULT 0);
CREATE TABLE skus(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES products(id),sku_code text UNIQUE NOT NULL,option_snapshot jsonb NOT NULL DEFAULT '{}',price numeric(12,2) NOT NULL CHECK(price>=0),stock_mode text NOT NULL DEFAULT 'tracked' CHECK(stock_mode IN('tracked','unlimited')),stock_on_hand bigint NOT NULL DEFAULT 0 CHECK(stock_on_hand>=0),active boolean NOT NULL DEFAULT true);
CREATE TABLE inventory_movements(id bigserial PRIMARY KEY,sku_id uuid NOT NULL REFERENCES skus(id),movement_type text NOT NULL,quantity_delta bigint NOT NULL,reference_type text,reference_id uuid,actor_user_id uuid REFERENCES users(id),note text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE carts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cart_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),cart_id uuid NOT NULL REFERENCES carts(id),sku_id uuid NOT NULL REFERENCES skus(id),quantity int NOT NULL CHECK(quantity>0),UNIQUE(cart_id,sku_id));
CREATE TABLE addresses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),recipient text NOT NULL,phone text NOT NULL,address_text text NOT NULL,delivery_note text,is_default boolean NOT NULL DEFAULT false);
CREATE TABLE orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_no text UNIQUE NOT NULL,buyer_user_id uuid NOT NULL REFERENCES users(id),status text NOT NULL DEFAULT 'pending_payment',item_amount numeric(12,2) NOT NULL CHECK(item_amount>=0),discount_amount numeric(12,2) NOT NULL DEFAULT 0,shipping_amount numeric(12,2) NOT NULL DEFAULT 0,payable_amount numeric(12,2) NOT NULL CHECK(payable_amount>=0),paid_at timestamptz,cancelled_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE merchant_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders(id),merchant_id uuid NOT NULL REFERENCES merchants(id),status text NOT NULL DEFAULT 'pending',item_amount numeric(12,2) NOT NULL,shipping_amount numeric(12,2) NOT NULL DEFAULT 0,merchant_fee numeric(12,2) NOT NULL DEFAULT 0,net_amount numeric(12,2) NOT NULL DEFAULT 0,UNIQUE(order_id,merchant_id));
CREATE TABLE order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),merchant_order_id uuid NOT NULL REFERENCES merchant_orders(id),product_id uuid REFERENCES products(id),sku_id uuid REFERENCES skus(id),product_title_snapshot text NOT NULL,sku_snapshot jsonb NOT NULL DEFAULT '{}',unit_price numeric(12,2) NOT NULL,quantity int NOT NULL CHECK(quantity>0),refunded_quantity int NOT NULL DEFAULT 0 CHECK(refunded_quantity BETWEEN 0 AND quantity),line_total numeric(12,2) NOT NULL);
CREATE TABLE order_status_history(id bigserial PRIMARY KEY,order_id uuid NOT NULL REFERENCES orders(id),old_status text,new_status text NOT NULL,actor_user_id uuid REFERENCES users(id),note text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE shipments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),merchant_order_id uuid NOT NULL REFERENCES merchant_orders(id),carrier text,tracking_no text,status text NOT NULL DEFAULT 'preparing',shipped_at timestamptz,delivered_at timestamptz);
CREATE TABLE shipment_items(shipment_id uuid REFERENCES shipments(id),order_item_id uuid REFERENCES order_items(id),quantity int NOT NULL CHECK(quantity>0),PRIMARY KEY(shipment_id,order_item_id));
CREATE TABLE wallets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_type text NOT NULL CHECK(owner_type IN('user','merchant','platform')),owner_id uuid NOT NULL,currency char(3) NOT NULL DEFAULT 'CNY',status text NOT NULL DEFAULT 'active',UNIQUE(owner_type,owner_id,currency));
CREATE TABLE wallet_transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),wallet_id uuid NOT NULL REFERENCES wallets(id),transaction_no text UNIQUE NOT NULL,transaction_type text NOT NULL,amount numeric(14,2) NOT NULL CHECK(amount>0),direction text NOT NULL CHECK(direction IN('credit','debit')),status text NOT NULL DEFAULT 'posted',reference_type text,reference_id uuid,idempotency_key text UNIQUE NOT NULL,description text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders(id),wallet_transaction_id uuid REFERENCES wallet_transactions(id),amount numeric(12,2) NOT NULL,status text NOT NULL,idempotency_key text UNIQUE NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE aftersales_cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),case_no text UNIQUE NOT NULL,order_id uuid NOT NULL REFERENCES orders(id),order_item_id uuid REFERENCES order_items(id),buyer_user_id uuid NOT NULL REFERENCES users(id),reason text NOT NULL,requested_amount numeric(12,2) NOT NULL,status text NOT NULL DEFAULT 'requested',platform_intervention boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz);
CREATE TABLE refunds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),case_id uuid NOT NULL REFERENCES aftersales_cases(id),amount numeric(12,2) NOT NULL CHECK(amount>0),status text NOT NULL DEFAULT 'pending',idempotency_key text UNIQUE NOT NULL,approved_by uuid REFERENCES users(id),completed_at timestamptz);
CREATE TABLE ledger_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text UNIQUE NOT NULL,name text NOT NULL,account_type text NOT NULL CHECK(account_type IN('asset','liability','equity','income','expense')));
CREATE TABLE journal_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entry_no text UNIQUE NOT NULL,source_type text NOT NULL,source_id uuid NOT NULL,status text NOT NULL DEFAULT 'posted',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(source_type,source_id));
CREATE TABLE journal_lines(id bigserial PRIMARY KEY,entry_id uuid NOT NULL REFERENCES journal_entries(id),account_id uuid NOT NULL REFERENCES ledger_accounts(id),debit numeric(14,2) NOT NULL DEFAULT 0 CHECK(debit>=0),credit numeric(14,2) NOT NULL DEFAULT 0 CHECK(credit>=0),wallet_id uuid REFERENCES wallets(id),CHECK((debit=0) <> (credit=0)));
CREATE TABLE settlement_batches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),merchant_id uuid NOT NULL REFERENCES merchants(id),amount numeric(14,2) NOT NULL,status text NOT NULL DEFAULT 'pending',requested_at timestamptz NOT NULL DEFAULT now(),approved_by uuid REFERENCES users(id),settled_at timestamptz);
CREATE TABLE settlement_items(batch_id uuid REFERENCES settlement_batches(id),merchant_order_id uuid REFERENCES merchant_orders(id),amount numeric(14,2) NOT NULL,PRIMARY KEY(batch_id,merchant_order_id));
CREATE TABLE merchant_fees(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),merchant_id uuid REFERENCES merchants(id),fee_type text NOT NULL,rate numeric(8,5),fixed_amount numeric(12,2),starts_at timestamptz NOT NULL,ends_at timestamptz,approved_by uuid REFERENCES users(id),reason text NOT NULL);
CREATE TABLE merchant_guarantees(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),merchant_id uuid NOT NULL REFERENCES merchants(id),amount numeric(12,2) NOT NULL,paid_at timestamptz,policy_snapshot jsonb NOT NULL DEFAULT '{}');
CREATE TABLE promotions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,platform_share numeric(5,2) NOT NULL DEFAULT 0,merchant_share numeric(5,2) NOT NULL DEFAULT 100,status text NOT NULL DEFAULT 'draft',CHECK(platform_share+merchant_share=100));
CREATE TABLE promotion_merchants(promotion_id uuid REFERENCES promotions(id),merchant_id uuid REFERENCES merchants(id),approved_by uuid REFERENCES users(id),PRIMARY KEY(promotion_id,merchant_id));
CREATE TABLE policy_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),policy_key text NOT NULL,version int NOT NULL,content jsonb NOT NULL,effective_at timestamptz NOT NULL,created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(policy_key,version));
CREATE TABLE reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_item_id uuid NOT NULL REFERENCES order_items(id),buyer_user_id uuid NOT NULL REFERENCES users(id),rating smallint NOT NULL CHECK(rating BETWEEN 1 AND 5),content text,status text NOT NULL DEFAULT 'visible',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(order_item_id,buyer_user_id));
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),channel text NOT NULL,template_key text NOT NULL,payload jsonb NOT NULL DEFAULT '{}',read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE conversation_members(conversation_id uuid REFERENCES conversations(id),user_id uuid REFERENCES users(id),joined_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(conversation_id,user_id));
CREATE TABLE messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id uuid NOT NULL REFERENCES conversations(id),sender_user_id uuid NOT NULL REFERENCES users(id),body text,message_type text NOT NULL DEFAULT 'text',attachment_key text,created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE TABLE files(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_user_id uuid NOT NULL REFERENCES users(id),object_key text UNIQUE NOT NULL,mime_type text NOT NULL,byte_size bigint NOT NULL CHECK(byte_size>=0),checksum text,visibility text NOT NULL DEFAULT 'private',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE file_access_logs(id bigserial PRIMARY KEY,file_id uuid REFERENCES files(id),actor_user_id uuid REFERENCES users(id),action text NOT NULL,ip inet,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE moderation_cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),target_type text NOT NULL,target_id uuid NOT NULL,reason text NOT NULL,status text NOT NULL DEFAULT 'open',reviewer_user_id uuid REFERENCES users(id),decision text,created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz);
CREATE TABLE audit_logs(id bigserial PRIMARY KEY,actor_user_id uuid REFERENCES users(id),action text NOT NULL,target_type text,target_id text,before_data jsonb,after_data jsonb,reason text,ip inet,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE approval_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_type text NOT NULL,requester_id uuid NOT NULL REFERENCES users(id),payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pending',reviewer_id uuid REFERENCES users(id),reviewed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE data_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),request_type text NOT NULL CHECK(request_type IN('export','deletion')),status text NOT NULL DEFAULT 'requested',requested_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,handled_by uuid REFERENCES users(id));
CREATE TABLE system_announcements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,body text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz,status text NOT NULL DEFAULT 'draft',created_by uuid REFERENCES users(id));
CREATE TABLE feature_controls(key text PRIMARY KEY,enabled boolean NOT NULL,reason text,changed_by uuid REFERENCES users(id),changed_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_products_merchant_status ON products(merchant_id,status) WHERE deleted_at IS NULL;
CREATE INDEX idx_skus_product_active ON skus(product_id,active);
CREATE INDEX idx_inventory_sku_created ON inventory_movements(sku_id,created_at DESC);
CREATE INDEX idx_orders_buyer_created ON orders(buyer_user_id,created_at DESC);
CREATE INDEX idx_merchant_orders_merchant_status ON merchant_orders(merchant_id,status);
CREATE INDEX idx_aftersales_order_status ON aftersales_cases(order_id,status);
CREATE INDEX idx_wallet_tx_wallet_created ON wallet_transactions(wallet_id,created_at DESC);
CREATE INDEX idx_auth_sessions_user_expiry ON auth_sessions(user_id,expires_at) WHERE revoked_at IS NULL;
CREATE INDEX idx_messages_conversation_created ON messages(conversation_id,created_at);
CREATE INDEX idx_audit_logs_target ON audit_logs(target_type,target_id,created_at DESC);
-- Follow-up reliability structures are drafted in 0003_inventory_finance_reliability_v1_draft.sql.
-- Both migrations remain unexecuted drafts. Atomic stock/payment/refund/settlement services,
-- outbox publisher/consumer, payout reconciliation, and integration tests are still required.
COMMIT;
